<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {RefreshCw,Search,ChevronLeft,ChevronRight,ArrowRight,X} from '@lucide/vue';
import {refreshFeedback as vRefreshFeedback} from '../../../shared/directives/refreshFeedback';
import {assetApi} from '../api';
import {useI18n} from '../uiPorts';
import type {ProjectSeed,ProjectSeedId,ProjectSeedPage,ProjectSeedDetail,ProjectSeedRoundPage} from '../seeds/types';
const props=defineProps<{projectId?:number;refreshVersion?:number;discoverLabel?:string}>();
const emit=defineEmits<{discover:[]}>();
const {tr}=useI18n();
const data=ref<ProjectSeedPage>(),detail=ref<ProjectSeedDetail>(),selectedId=ref<ProjectSeedId>();
const roundData=ref<ProjectSeedRoundPage>(),roundReading=ref(false),roundError=ref('');
const search=ref(''),kind=ref('all'),trust=ref('all'),page=ref(1),pageSize=ref(50),detailPage=ref(1);
const reading=ref(false),detailReading=ref(false),initializing=ref(false),error=ref(''),detailError=ref(''),prepareError=ref('');
let generation=0,sequence=0,detailSequence=0,roundSequence=0,disposed=false,prepared=false,searchTimer:ReturnType<typeof setTimeout>|undefined,pollTimer:ReturnType<typeof setTimeout>|undefined;
const pages=computed(()=>Math.max(1,Math.ceil((data.value?.total||0)/pageSize.value)));
const historyPages=computed(()=>Math.max(1,Math.ceil((detail.value?.observationsTotal||0)/(detail.value?.pageSize||20))));
const summary=computed(()=>data.value?.summary);
const rounds=computed(()=>roundData.value?.items||[]);
const roundPages=computed(()=>Math.max(1,Math.ceil((roundData.value?.total||0)/10)));
const selected=computed(()=>detail.value?.seed||data.value?.items.find(row=>row.id===selectedId.value));
const kinds:Record<string,[string,string]>={domain:['域名','Domain'],fingerprint:['证书 SHA-256','Certificate SHA-256'],cname:['CNAME','CNAME']};
const trusts:Record<string,[string,string]>={verified:['证据已核验','Evidence verified'],needs_evidence:['自动待补证','Awaiting evidence'],conflict:['证据冲突','Conflicting evidence'],excluded:['已排除','Excluded']};
const sources:Record<string,[string,string]>={hunter_query:['Hunter 查询','Hunter query'],hunter_page:['Hunter 分页','Hunter page'],hunter_result:['Hunter 关联结果','Hunter related result'],public_ct:['公开 CT 记录','Public CT record'],free_tls:['TLS 补采','TLS enrichment'],free_ct:['CT 发现','CT discovery'],free_dns:['DNS 发现','DNS discovery'],free_dns_a:['DNS IPv4 地址','DNS IPv4 records'],free_dns_aaaa:['DNS IPv6 地址','DNS IPv6 records'],free_dns_cname:['DNS 别名','DNS aliases'],free_tls_previous_leaf:['历史 TLS 叶证书','Previous TLS leaf certificate'],free_cname:['CNAME 发现','CNAME discovery'],fofa:['FOFA','FOFA'],hunter:['Hunter','Hunter'],tls:['TLS 证书','TLS certificate'],ct:['证书透明度','Certificate transparency'],dns:['DNS / CNAME','DNS / CNAME'],history:['历史记录','Historical record'],historical_baseline:['历史基线','Historical baseline'],certificate_sha256:['证书指纹','Certificate fingerprint'],certificate_name:['证书名称','Certificate name'],certificate_cn:['证书 CN','Certificate CN'],certificate_domain:['测绘证书关联','Provider certificate relation'],certificate_transparency:['证书透明度','Certificate transparency'],public_ct_subject:['公开 CT 叶证书','Public CT leaf certificate'],dns_cname:['DNS CNAME','DNS CNAME'],cname:['CNAME','CNAME'],observed_host:['已收录主机','Observed host'],confirmed_scope:['已确认范围','Confirmed scope'],page:['已采集页面','Collected page'],page_or_inline_script:['页面 / 内联脚本','Page / inline script']};
const kindLabel=(value:string)=>kinds[value]?tr(...kinds[value]):value;
const seedValue=(seed:ProjectSeed)=>seed.wildcard&&!seed.value.startsWith('*.')?`*.${seed.value}`:seed.value;
const assetIds=(entry:{assetId?:number|null;assetIds?:number[]})=>entry.assetIds?.length?entry.assetIds:entry.assetId!=null?[entry.assetId]:[];
const trustLabel=(value:string)=>trusts[value]?tr(...trusts[value]):tr('状态未识别','Unknown status');
const sourceLabel=(value:string)=>sources[value]?tr(...sources[value]):value;
const roundState=(value:string)=>({active:tr('执行中','Active'),superseded:tr('已切换目标，历史保留','Target changed; history retained'),running:tr('执行中','Running'),paused:tr('已暂停','Paused'),completed:tr('已完成','Completed'),interrupted:tr('已中断','Interrupted'),failed:tr('失败','Failed'),blocked:tr('待恢复','Blocked'),steady:tr('本轮完成','Round complete'),collecting:tr('采集中','Collecting')} as Record<string,string>)[value]||value;
const roundLabel=(value:number|null|undefined)=>typeof value==='number'&&Number.isFinite(value)?tr(`第 ${value} 轮`,`Round ${value}`):tr('历史基线 · 轮次未知','Historical baseline · round unknown');
const numberLabel=(value:number|null|undefined)=>typeof value==='number'&&Number.isFinite(value)?value.toLocaleString():tr('未记录','Not recorded');
function timeLabel(value:string|null|undefined){if(!value)return tr('时间未记录','Time not recorded');const date=new Date(/Z$|[+-]\d\d:\d\d$/.test(value)?value:value.replace(' ','T')+'Z');return Number.isNaN(date.getTime())?value:date.toLocaleString(tr('zh-CN','en-US'),{hour12:false});}
function evidenceText(value:unknown){return typeof value==='string'?value:JSON.stringify(value,null,2);}
function clearSelection(){selectedId.value=undefined;detail.value=undefined;detailError.value='';detailReading.value=false;detailPage.value=1;detailSequence++;}
function poll(projectId:number,g:number){clearTimeout(pollTimer);pollTimer=setTimeout(()=>{if(!disposed&&g===generation&&props.projectId===projectId&&!prepareError.value)void loadList();},1500);}
async function prepare(projectId:number,g:number){
 if(prepared||disposed||g!==generation)return;prepared=true;initializing.value=true;
 try{await assetApi.prepareProjectSeeds(projectId);if(!disposed&&g===generation)poll(projectId,g);}
 catch(e){if(!disposed&&g===generation){prepareError.value=String(e);clearTimeout(pollTimer);}}
 finally{if(!disposed&&g===generation)initializing.value=false;}
}
async function loadList(){
 const projectId=props.projectId,g=generation,seq=++sequence;if(!projectId||disposed)return;reading.value=true;
 try{const value=await assetApi.listProjectSeeds({projectId,search:search.value.trim(),kind:kind.value,trust:trust.value,page:page.value,pageSize:pageSize.value});
  if(disposed||g!==generation||seq!==sequence)return;if(value.projectId!==projectId||!Array.isArray(value.items))throw Error('project_seed_scope_mismatch');data.value=value;error.value='';
  if(!roundData.value||roundData.value.page===1)roundData.value={projectId,items:value.rounds||[],total:value.roundsTotal??value.rounds?.length??0,page:1,pageSize:10,historyBeforeTracking:'unknown'};
  if(value.ready===false){if(!prepared)void prepare(projectId,g);if(!prepareError.value)poll(projectId,g);}else clearTimeout(pollTimer);
  return true;
 }catch(e){if(g===generation&&seq===sequence&&!disposed){error.value=String(e);return false;}}finally{if(g===generation&&seq===sequence&&!disposed)reading.value=false;}
}
async function loadDetail(){
 const projectId=props.projectId,seedId=selectedId.value,g=generation,seq=++detailSequence;if(!projectId||seedId===undefined||disposed)return;detailReading.value=true;
 try{const value=await assetApi.readProjectSeed(projectId,seedId,detailPage.value,20);if(disposed||g!==generation||seq!==detailSequence)return;
  if(value.projectId!==projectId||value.seed.id!==seedId||!Array.isArray(value.observations))throw Error('project_seed_detail_scope_mismatch');detail.value=value;detailError.value='';return true;
 }catch(e){if(g===generation&&seq===detailSequence&&!disposed){detailError.value=String(e);return false;}}finally{if(g===generation&&seq===detailSequence&&!disposed)detailReading.value=false;}
}
async function selectSeed(row:ProjectSeed){if(selectedId.value===row.id&&detail.value)return;clearSelection();selectedId.value=row.id;await loadDetail();}
async function loadRoundPage(value:number){
 const projectId=props.projectId,g=generation,seq=++roundSequence;if(!projectId||disposed)return;roundReading.value=true;
 try{const result=await assetApi.listProjectSeedRounds(projectId,Math.max(1,Math.min(roundPages.value,value)),10);if(disposed||g!==generation||seq!==roundSequence)return;
  if(result.projectId!==undefined&&result.projectId!==projectId||!Array.isArray(result.items))throw Error('project_seed_round_scope_mismatch');roundData.value=result;roundError.value='';
 }catch(e){if(!disposed&&g===generation&&seq===roundSequence)roundError.value=String(e);}finally{if(!disposed&&g===generation&&seq===roundSequence)roundReading.value=false;}
}
async function refresh(){await Promise.all([loadList(),...(selectedId.value!==undefined?[loadDetail()]:[]),...(roundData.value&&roundData.value.page>1?[loadRoundPage(roundData.value.page)]:[])]);}
function resetFilter(){clearTimeout(searchTimer);page.value=1;clearSelection();void loadList();}
function searchSeeds(){clearTimeout(searchTimer);searchTimer=setTimeout(resetFilter,250);}
async function changePage(value:number){if(reading.value)return;const previous=page.value,g=generation;page.value=Math.max(1,Math.min(pages.value,value));clearSelection();const request=loadList(),seq=sequence;if(await request===false&&g===generation&&seq===sequence&&!disposed)page.value=previous;}
async function changeHistoryPage(value:number){if(detailReading.value)return;const previous=detailPage.value,g=generation;detailPage.value=Math.max(1,Math.min(historyPages.value,value));const request=loadDetail(),seq=detailSequence;if(await request===false&&g===generation&&seq===detailSequence&&!disposed)detailPage.value=previous;}
watch([kind,trust,pageSize],resetFilter);
watch(()=>props.projectId,()=>{generation++;sequence++;detailSequence++;roundSequence++;roundData.value=undefined;roundReading.value=false;roundError.value='';clearTimeout(searchTimer);clearTimeout(pollTimer);prepared=false;initializing.value=false;prepareError.value='';page.value=1;data.value=undefined;error.value='';reading.value=false;clearSelection();if(props.projectId)void loadList();},{immediate:true,flush:'sync'});
watch(()=>props.refreshVersion,()=>void refresh());
onUnmounted(()=>{disposed=true;generation++;sequence++;detailSequence++;roundSequence++;clearTimeout(searchTimer);clearTimeout(pollTimer);});
</script>
<template>
<section class="project-seeds" data-testid="project-seeds-workspace">
 <header class="seed-heading"><div><span class="eyebrow">PROJECT SEEDS</span><h2>{{tr('项目种子','Project seeds')}}</h2><p>{{tr('按项目保留每次发现、证据与查询历史；核验状态不代表资产当前存活或探测授权。','Retains discovery, evidence and query history for this project. Verification does not prove current liveness or grant probing permission.')}}</p></div><div class="seed-heading-actions"><button v-refresh-feedback="{scope:projectId,busy:reading||detailReading||roundReading,error:error||detailError||prepareError||roundError}" class="button ghost compact" :disabled="!projectId||reading||detailReading||roundReading" data-seeds-action="refresh" @click="refresh"><RefreshCw :size="15"/>{{tr('刷新','Refresh')}}</button><button v-if="projectId" class="button primary compact" data-seeds-action="discover" @click="emit('discover')">{{discoverLabel||tr('继续增量发现','Continue incremental discovery')}}<ArrowRight :size="14"/></button></div></header>
 <p v-if="!projectId" class="seed-empty">{{tr('先选择一个工作空间，种子及历史仅在本项目内读取。','Choose a workspace. Seeds and their history are read only within that project.')}}</p>
 <template v-else>
  <p v-if="data?.ready===false" class="seed-initializing" role="status">{{prepareError?tr('历史种子整理尚未确认，可刷新状态或稍后重新进入。','Historical seed preparation is unconfirmed. Refresh status or return later.'):tr('正在整理历史种子，仅建立本地索引，不调用 AI、不联网、不消耗 Hunter 积分。','Preparing historical seeds locally. No AI, network or Hunter points are used.')}} <span v-if="prepareError" class="seed-error">{{prepareError}}</span></p>
  <details v-if="roundData&&roundData.total>0" class="seed-rounds"><summary>{{tr('发现轮次','Discovery rounds')}} · {{numberLabel(roundData.total)}} {{tr('轮','rounds')}}</summary><div><article v-for="round in rounds" :key="round.number"><b>{{roundLabel(round.number)}}</b><span>{{roundState(round.state)}}</span><small v-if="round.plannedQueries!=null">{{tr('精确查询','Exact queries')}} {{round.plannedQueries}}</small><time>{{timeLabel(round.startedAt)}} → {{round.completedAt?timeLabel(round.completedAt):tr('结束时间未记录','End time not recorded')}}</time></article></div><p>{{tr('暂停后恢复沿用同一轮；开始记录之前的历史轮次未知。','Resuming retains the same round. Historical rounds before tracking are unknown.')}}</p><p v-if="roundError" class="seed-error" role="alert">{{roundError}} · {{tr('保留上页历史','Previous history retained')}}</p><footer v-if="roundPages>1" class="seed-pagination"><span>{{roundData.page}} / {{roundPages}}</span><button class="button ghost compact" :disabled="roundReading||roundData.page<=1" data-seeds-action="previous-rounds" @click="loadRoundPage(roundData.page-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="roundReading||roundData.page>=roundPages" data-seeds-action="next-rounds" @click="loadRoundPage(roundData.page+1)"><ChevronRight :size="14"/></button></footer></details>
  <div v-if="summary" class="seed-metrics"><span>{{tr('项目全部种子','All project seeds')}} <b>{{numberLabel(summary.total)}}</b></span><span>{{tr('证据已核验','Evidence verified')}} <b>{{numberLabel(summary.verified)}}</b></span><span>{{tr('自动待补证','Awaiting evidence')}} <b>{{numberLabel(summary.needsEvidence)}}</b></span><span>{{tr('证据冲突','Evidence conflicts')}} <b>{{numberLabel(summary.conflicts)}}</b></span><span>{{tr('已排除','Excluded')}} <b>{{numberLabel(summary.excluded)}}</b></span><span>{{tr('历史基线','Historical baseline')}} <b>{{numberLabel(summary.historicalBaseline)}}</b></span></div>
  <div class="seed-filters"><label class="seed-search"><Search :size="15"/><input v-model="search" maxlength="240" :placeholder="tr('搜索域名、证书指纹或 CNAME','Search domains, certificate fingerprints or CNAME')" :aria-label="tr('搜索项目种子','Search project seeds')" @input="searchSeeds"/></label><select v-model="kind" :aria-label="tr('种子类型','Seed type')"><option value="all">{{tr('全部种子类型','All seed types')}}</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{tr(...label)}}</option></select><select v-model="trust" :aria-label="tr('可信状态','Verification status')"><option value="all">{{tr('全部可信状态','All verification states')}}</option><option v-for="(label,key) in trusts" :key="key" :value="key">{{tr(...label)}}</option></select></div>
  <p v-if="error" class="seed-error" role="alert">{{error}}<span v-if="data"> · {{tr('显示上次快照，当前读数尚未确认。','Showing the previous snapshot; current counts are unconfirmed.')}}</span></p>
  <div class="seed-content" :class="{selected:selectedId!==undefined}">
   <div class="seed-list-pane" :aria-busy="reading"><div class="seed-table-scroll"><table class="seed-table"><thead><tr><th>{{tr('种子 / 类型','Seed / type')}}</th><th>{{tr('核验状态','Verification')}}</th><th>{{tr('首次发现','First seen')}}</th><th>{{tr('最近出现','Last seen')}}</th><th>{{tr('来源','Sources')}}</th><th>{{tr('相关资产','Related assets')}}</th><th/></tr></thead><tbody><tr v-for="row in data?.items" :key="row.id" :class="{'is-selected':selectedId===row.id}"><td data-label="种子"><small class="seed-kind">{{kindLabel(row.kind)}}</small><button class="seed-value" :data-seed-id="row.id" @click="selectSeed(row)">{{seedValue(row)}}</button></td><td data-label="核验状态"><span class="seed-trust" :class="row.trustStatus">{{trustLabel(row.trustStatus)}}</span><small class="seed-trust-reason">{{row.trustReason}}</small></td><td data-label="首次发现"><span>{{roundLabel(row.firstSeenRound)}}</span><small>{{timeLabel(row.firstSeenAt)}}</small></td><td data-label="最近出现"><span>{{timeLabel(row.lastSeenAt)}}</span><small v-if="row.historicalBaseline&&row.lastSeenRound==null">{{tr('台账记录时间','Ledger record time')}}</small><small v-if="row.lastSeenRound!==undefined&&row.lastSeenRound!==null">{{roundLabel(row.lastSeenRound)}}</small></td><td data-label="来源"><div class="seed-sources"><span v-for="source in row.sourceTypes" :key="source">{{sourceLabel(source)}}</span></div><small>{{numberLabel(row.observationCount)}} {{tr('条历史观察','historical observations')}}</small></td><td data-label="相关资产" class="seed-count">{{numberLabel(row.assetCount)}}</td><td><button class="button ghost compact" :data-seed-detail="row.id" @click="selectSeed(row)">{{tr('详情','Details')}}</button></td></tr></tbody></table><p v-if="!data?.items.length" class="seed-empty" role="status">{{reading?tr('正在读取项目种子…','Reading project seeds…'):error?tr('当前结果未知，不代表没有种子。','The current result is unknown, not empty.'):data?.ready===false?tr('本地历史索引尚未就绪，当前数量未知。','The local historical index is not ready; counts are unknown.'):tr('没有匹配的项目种子。已有历史记录会保留；发现流程会继续补充新观察。','No matching seeds. Historical records remain; discovery can append new observations.')}}</p></div>
    <footer class="seed-pagination"><span>{{tr('匹配','Matches')}} {{numberLabel(data?.total)}} · {{page}} / {{pages}}</span><select v-model.number="pageSize" :aria-label="tr('每页条数','Rows per page')"><option :value="25">25 / {{tr('页','page')}}</option><option :value="50">50 / {{tr('页','page')}}</option></select><button class="button ghost compact" :disabled="reading||page<=1" data-seeds-action="previous" @click="changePage(page-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="reading||page>=pages" data-seeds-action="next" @click="changePage(page+1)"><ChevronRight :size="14"/></button></footer>
   </div>
   <aside v-if="selectedId!==undefined" class="seed-detail" :aria-busy="detailReading" aria-label="种子证据与历史"><header><h3>{{tr('证据与查询历史','Evidence and query history')}}</h3><button class="button ghost compact" :aria-label="tr('收起种子详情','Close seed details')" data-seeds-action="close-detail" @click="clearSelection"><X :size="15"/></button></header><template v-if="selected"><small>{{kindLabel(selected.kind)}}</small><code class="detail-seed-value">{{seedValue(selected)}}</code><span class="seed-trust" :class="selected.trustStatus">{{trustLabel(selected.trustStatus)}}</span><p>{{selected.trustReason}}</p><div class="seed-detail-facts"><span>{{tr('相关资产','Related assets')}} <b>{{numberLabel(selected.assetCount)}}</b></span><span v-if="selected.hunterEligible!==undefined">{{tr('Hunter 查询条件','Hunter eligibility')}} <b>{{selected.hunterEligible?tr('已满足','Eligible'):tr('未满足','Not eligible')}}</b></span></div><p v-if="selected.verificationCoverage" class="seed-coverage">{{tr('独立核验依据','Independent verification evidence')}} {{selected.verificationCoverage.verifiedEvidence}} {{tr('条','records')}} · {{tr('历史观察记录','Historical observations')}} {{selected.verificationCoverage.totalEvidence}} {{tr('条','records')}}<small>{{tr('历史观察包含查询页和状态记录，不作为核验证据分母。这些数量不是 AI 准确率或资产归属准确率。','Historical observations include query pages and status records; they are not a denominator for verified evidence. These counts are not AI accuracy or ownership accuracy.')}}</small></p><p v-if="selected.manualConclusion" class="seed-coverage">{{tr('已审样本','Reviewed samples')}} · {{selected.manualConclusion.reviewed}} / {{selected.manualConclusion.total}}<small>{{tr('认可','Accepted')}} {{selected.manualConclusion.accepted}} · {{tr('排除','Rejected')}} {{selected.manualConclusion.rejected}}<template v-if="selected.manualConclusion.reviewed>0&&selected.manualConclusion.acceptanceRate!=null"> · {{tr('人工已审样本认可率','Reviewed sample acceptance')}} {{(selected.manualConclusion.acceptanceRate*100).toFixed(1)}}%</template></small></p></template><p v-if="detailError" class="seed-error" role="alert">{{detailError}}<button class="button ghost compact" data-seeds-action="retry-detail" @click="loadDetail">{{tr('重试读取','Retry read')}}</button></p><p v-else-if="detailReading" class="seed-read-status" role="status">{{tr('正在读取历史，本页不会启动外部查询。','Reading history. This page does not start external queries.')}}</p>
    <div class="seed-history"><article v-for="entry in detail?.observations" :key="entry.id"><div class="history-title"><strong>{{sourceLabel(entry.sourceType)}}</strong><time>{{entry.historicalBaseline?tr('台账记录时间 · ','Ledger recorded · '):''}}{{timeLabel(entry.seenAt)}}</time></div><span class="history-round">{{roundLabel(entry.round)}}</span><p v-if="entry.sourceRef" class="history-reference">{{entry.sourceRef}}</p><div v-if="entry.queryKind||entry.queryId||entry.page!=null||entry.spentPoints!=null||entry.costUnknown" class="history-query"><span v-if="entry.queryKind">{{entry.queryKind}}</span><span v-if="entry.page!=null">{{tr('第','Page')}} {{entry.page}} {{tr('页','')}}</span><span v-if="entry.costUnknown" class="seed-error">{{tr('扣费待核对','Charge unresolved')}}</span><span v-else-if="entry.spentPoints!=null">{{entry.spentPoints}} {{tr('积分','points')}}</span><span v-else-if="entry.queryId||entry.page!=null">{{tr('积分未记录','Points not recorded')}}</span><small v-if="entry.queryId">{{entry.queryId}}</small></div><code v-if="entry.queryValue" class="history-query-value">{{entry.queryValue}}</code><small v-if="entry.assetCount!==undefined">{{tr('关联资产','Related assets')}} {{numberLabel(entry.assetCount)}}</small><details v-if="entry.evidence||assetIds(entry).length"><summary>{{tr('查看关联依据','View related evidence')}}</summary><p v-if="assetIds(entry).length">{{tr('资产编号','Asset IDs')}} · {{assetIds(entry).join('、')}}</p><pre v-if="entry.evidence">{{evidenceText(entry.evidence)}}</pre></details></article><p v-if="detail&&!detail.observations.length" class="seed-empty">{{tr('尚无可展示的历史观察；首次时间和轮次不作推断。','No historical observations are available. First-seen time and round are not inferred.')}}</p></div>
    <footer v-if="detail" class="seed-pagination history-pagination"><span>{{numberLabel(detail.observationsTotal)}} {{tr('条历史','observations')}} · {{detailPage}} / {{historyPages}}</span><button class="button ghost compact" :disabled="detailReading||detailPage<=1" data-seeds-action="previous-history" @click="changeHistoryPage(detailPage-1)"><ChevronLeft :size="14"/></button><button class="button ghost compact" :disabled="detailReading||detailPage>=historyPages" data-seeds-action="next-history" @click="changeHistoryPage(detailPage+1)"><ChevronRight :size="14"/></button></footer>
   </aside>
  </div>
 </template>
</section>
